package io.github.diodeme.ji.storage.sqlite;

import java.sql.Connection;
import java.sql.SQLException;

/** Classifies an exact known unversioned SQLite schema before forward migration. */
@FunctionalInterface
public interface LegacySchemaClassifier {
    /** Returns zero for an empty database, a known baseline version, or {@code -1} for an unknown schema. */
    int classify(Connection connection) throws SQLException;
}
